INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m29059$nota-0223$m29059$, $m29060$Exercise Physiology McArdle.pdf$m29060$, $m29061$39$m29061$, $m29062$the protein RDA equals 0.83 g per kilogram of body mass. To determine the protein requirement for men and women ages 18 to 65, multiply body mass in kg by 0.83.$m29062$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m29063$nota-0223$m29063$, $m29064$Exercise Physiology McArdle.pdf$m29064$, $m29065$38$m29065$, $m29066$Based on the available evidence, athletes who train intensely should consume between 1.2 and 1.8 g of protein per kg of body mass daily... Protein intake greater than the 1.8 g value offers no further advantage to athletes with regard to whole-body protein use.$m29066$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m29067$nota-0223$m29067$, $m29068$Exercise Physiology McArdle.pdf$m29068$, $m29069$38$m29069$, $m29070$a reasonable daily protein intake for vegetarian athletes ranges between 1.3 and 1.8 g per kilogram of body weight.$m29070$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m29071$nota-0223$m29071$, $m29072$nota-0224$m29072$, $m29073$complementa$m29073$, $m29074$explica um dos mecanismos (ciclo alanina-glicose) que aumenta a demanda de proteína como combustível durante exercício prolongado, justificando a faixa mais alta de 1,2-1,8 g/kg$m29074$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m29075$nota-0224$m29075$, $m29076$Exercise Physiology McArdle.pdf$m29076$, $m29077$38$m29077$, $m29078$Active skeletal muscle synthesizes alanine during transamination from the glucose intermediate pyruvate with nitrogen derived in part from the amino acid leucine... The newly formed alanine leaves the muscle and enters the liver for deamination. Alanine's remaining carbon skeleton converts to glucose via gluconeogenesis and enters the blood for delivery to active muscle.$m29078$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m29079$nota-0224$m29079$, $m29080$Exercise Physiology McArdle.pdf$m29080$, $m29081$38$m29081$, $m29082$After 4 hr of continuous light exercise, the liver's output of alanine-derived glucose accounts for about 45% of the liver's total glucose release. The alanine–glucose cycle generates from 10 to 15% of the total exercise energy requirement.$m29082$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m29083$nota-0224$m29083$, $m29084$nota-0223$m29084$, $m29085$complementa$m29085$, $m29086$explica um mecanismo pelo qual o exercício prolongado aumenta a demanda proteica, fundamentando a recomendação de 1,2-1,8 g/kg/dia para atletas de endurance$m29086$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m29087$nota-0225$m29087$, $m29088$Exercise Physiology McArdle.pdf$m29088$, $m29089$89$m29089$, $m29090$figure 3.7 outlines the variation in daily energy expenditure for a male competitor during the Tour de France professional cycling race. In this grueling sporting event, energy expenditure averaged 6500 kcal daily for nearly 3 weeks. Large variation occurred depending on activity level for a particular day; the daily energy expenditure decreased to about 3000 kcal on a 'rest' day and increased to 9000 kcal when cycling over a mountain pass.$m29090$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m29091$nota-0225$m29091$, $m29092$Exercise Physiology McArdle.pdf$m29092$, $m29093$89$m29093$, $m29094$Deficits have been reported among ultraendurance cyclists in a 16-hr, 384-km cycle race. For these athletes, mean energy intake averaged 18.7 MJ (4469 kcal) compared with an estimated energy requirement for the race of 25.5 MJ (6095 kcal). Of functional significance was the negative relationship between energy intake and time to complete the race, which suggests that reducing the energy deficit may be advantageous to race performance.$m29094$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m29095$nota-0225$m29095$, $m29096$nota-0002$m29096$, $m29097$complementa$m29097$, $m29098$usa a conversão kJ→kcal (nota-0002) como base para estimar gasto energético a partir do trabalho mecânico (trabalho-kJ) registrado pelo Strava$m29098$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m29099$nota-0226$m29099$, $m29100$Exercise Physiology McArdle.pdf$m29100$, $m29101$97$m29101$, $m29102$Optimal carbohydrate intake replenishes glycogen stores at about 5 to 7% per hour. Even under the best of circumstances, it takes at least 20 hr to reestablish glycogen stores following glycogen-depleting exercise.$m29102$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m29103$nota-0226$m29103$, $m29104$Exercise Physiology McArdle.pdf$m29104$, $m29105$97$m29105$, $m29106$the individual consumes about 50 to 75 g (2 to 3 oz) of high- to moderate-glycemic carbohydrates every 2 hr until achieving 500 to 700 g (7 to 10 g per kilogram of body mass) or until eating a large, high-carbohydrate meal.$m29106$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m29107$nota-0226$m29107$, $m29108$nota-0201$m29108$, $m29109$complementa$m29109$, $m29110$nota-0201 cobre a ingestão de carboidrato DURANTE o exercício; esta nota cobre a cinética de ressíntese de glicogênio APÓS o exercício, um dado numérico ainda não presente no cânone$m29110$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m29111$nota-0226$m29111$, $m29112$nota-0203$m29112$, $m29113$complementa$m29113$, $m29114$reforça, com um número concreto de taxa horária, por que a reposição de glicogênio é um processo de muitas horas (consistente com o mito da janela anabólica de 30min já refutado na nota-0203)$m29114$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m29115$nota-0227$m29115$, $m29116$Exercise Physiology McArdle.pdf$m29116$, $m29117$101$m29117$, $m29118$1. Monitor dehydration rate from changes in body weight; require urination before postexercise body weight measurement for precise determination of the body's total fluid loss. Each pound of weight loss corresponds to 450 mL (15 oz) of dehydration.$m29118$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m29119$nota-0227$m29119$, $m29120$Exercise Physiology McArdle.pdf$m29120$, $m29121$101$m29121$, $m29122$2. Drink fluids at the same rate as their estimated depletion (or at least drink at a rate close to 80% of sweating rate) during prolonged exercise that increases cardiovascular stress, metabolic heat load, and dehydration. 3. Achieve carbohydrate (30 to 60 g·hr−1) and fluid requirements by drinking a 4 to 8% carbohydrate beverage each hour (625 to 1250 mL; average 250 mL every 15 min).$m29122$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m29123$nota-0227$m29123$, $m29124$nota-0201$m29124$, $m29125$complementa$m29125$, $m29126$nota-0201 cobre a quantidade de carboidrato por hora numa tabela escalonada por duração (1-2h→30-60g/h, 2-3h→60-90g/h, >3h→90-120g/h); esta nota cobre o protocolo paralelo de reposição de fluido e cita a recomendação geral do McArdle (30-60g/h, sem escalonar por duração) — a faixa só coincide com nota-0201 na janela de 1-2h; para sessões mais longas, a tabela de nota-0201 é a referência mais granular e deve prevalecer, não o número fixo desta nota$m29126$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m29127$nota-0227$m29127$, $m29128$nota-0259$m29128$, $m29129$complementa$m29129$, $m29130$nota-0259 detalha o protocolo ACSM de volumes de fluido (antes/durante/depois), com o 'durante' chegando a 1180 mL/h no teto — acima do '~1000 mL/h' desta nota. Ver ressalva no corpo: os dois números cabem dentro da faixa prática de 600-1200 mL/h citada na literatura de ciência do esporte (limite de esvaziamento gástrico), não é uma contradição real, é variação individual dentro do mesmo intervalo aceito$m29130$)
